{"security_risk":"LOW","summary":"Check manifest for any extraction failures or low-confidence cases","command":"grep -n 'extract_failed' /root/papers_organized/manifest.tsv || echo 'No extraction failures'; echo '--- low-score candidates (max score < 2 and no arxiv cat):'; python3 - <<'PY'
import csv
from pathlib import Path
p=Path('/root/papers_organized/manifest.tsv')
rows=[]
with p.open('r',encoding='utf-8') as f:
    r=csv.DictReader(f, delimiter='\t')
    for row in r:
        scores={}
        for kv in row['scores'].split(','):
            k,v=kv.split(':')
            scores[k]=int(v)
        mx=max(scores.values())
        if mx<2 and not row['arxiv_cats']:
            rows.append((mx,row['subject'],Path(row['src']).name))
for mx,sub,name in sorted(rows)[:25]:
    print(mx, sub, name)
print('count', len(rows))
PY"}

